class Solution {
public:
    int maximumANDSum(vector<int>& nums, int numSlots) {
        int states=1;for(int i=0;i<numSlots;++i) states*=3;
        vector<int> dp(states,-1);dp[0]=0;int ans=0;
        for(int mask=0;mask<states;++mask) if(dp[mask]>=0) {
            int x=mask,used=0;
            for(int j=0;j<numSlots;++j){used+=x%3;x/=3;}
            if(used==(int)nums.size()){ans=max(ans,dp[mask]);continue;}
            int place=1;
            for(int j=0;j<numSlots;++j,place*=3) if((mask/place)%3<2)
                dp[mask+place]=max(dp[mask+place],dp[mask]+(nums[used]&(j+1)));
        }
        return ans;
    }
};
